package com.cafeteria.controller.admin;
import com.cafeteria.dto.request.CategoryRequest; import com.cafeteria.dto.response.CategoryResponse; import com.cafeteria.service.CategoryService; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin/categories") public class AdminCategoryController{private final CategoryService s;public AdminCategoryController(CategoryService s){this.s=s;}@GetMapping public List<CategoryResponse> all(){return s.getAllCategories();}@PostMapping public CategoryResponse create(@RequestBody CategoryRequest r){return s.createCategory(r);}@PutMapping("/{id}")public CategoryResponse update(@PathVariable Long id,@RequestBody CategoryRequest r){return s.updateCategory(id,r);}@PatchMapping("/{id}/active")public CategoryResponse active(@PathVariable Long id,@RequestParam boolean value){return s.setCategoryActive(id,value);}}
